package com.pilipala.tvinstaller;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.InputType;
import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.*;

public final class MainActivity extends Activity {
    private EditText ip,port;private TextView status,guide;private ProgressBar progress;private Button connect,install,open,find;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile AdbWire adb;private volatile int generation;private boolean busy;private String identity="";
    private final int ink=Color.rgb(233,239,249),muted=Color.rgb(165,181,203);private LinearLayout box;
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(13,21,34));getWindow().setNavigationBarColor(Color.rgb(13,21,34));ScrollView sc=new ScrollView(this);box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(22),dp(24),dp(22),dp(24));box.setBackgroundColor(Color.rgb(13,21,34));sc.addView(box);setContentView(sc);
        text("Marco TV 安装助手",26,ink);text("Pilipala · 免费开源 · 助手 1.0.0\n内含电视正式版 "+ReleaseInfo.VERSION,14,muted);
        text("01  准备电视",20,ink);guide=text("手机和电视连接同一家庭网络。在电视开启“网络调试 / ADB 调试”，查看网络详情中的 IP。仅 USB 调试不保证网络可连接。",15,muted);
        Spinner brands=new Spinner(this);String[] options={"选择电视系统查看提示","小米 / Redmi 国内旧版（部分机型）","Android TV / Google TV","TCL / 雷鸟 / 海信 / 创维等国内系统","非 Android 或不确定"};brands.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,options));box.addView(brands);
        brands.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){String[] tips={"手机和电视连接同一家庭网络；在电视查找网络调试和 IP。仅 USB 调试不保证能连接。","旧版常见：设置 → 账户与安全 → 允许 ADB 调试。新固件请按本机设置核对。","设置 → 系统 / 设备偏好设置 → 关于 → 连续选择版本号。开发者选项须提供普通网络调试。","先核对完整型号、系统和固件，查厂商帮助中的调试入口；不使用工程菜单密码。","要求 Android 6.0 以上。Tizen、webOS、Roku、tvOS 不适用。华为、荣耀、VIDAA 需先确认 APK 兼容性。"};guide.setText(tips[i]+"\n只有无线配对码、没有普通网络调试的电视，暂不支持此版助手。");}});
        text("02  连接你的电视",20,ink);ip=field("电视 IP（在电视网络详情查看）","");port=field("连接端口（以电视显示为准）","5555");
        find=button("查找同网电视（5555）",()->discover());connect=button("连接电视",()->connect());button("断开连接",()->{disconnect();say("已断开，电视现有应用不受影响。");});
        text("03  确认型号，再安装",20,ink);install=button("安装 Marco TV "+ReleaseInfo.VERSION,()->new AlertDialog.Builder(this).setTitle("确认目标电视").setMessage("将安装到："+identity+"\n保留原配置，不修改默认桌面或系统权限。").setPositiveButton("安装",(d,w)->install()).setNegativeButton("取消",null).show());open=button("打开电视上的 Marco TV",()->run(()->{require().shell("am start -n com.pilipala.tvhome/.MainActivity");say("已请求打开桌面，请看电视屏幕。");}));install.setEnabled(false);open.setEnabled(false);
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);box.addView(progress);status=text("准备好后连接电视，并用遥控器确认电视上的授权弹窗。安装不会卸载原厂桌面。",15,ink);status.setPadding(dp(12),dp(12),dp(12),dp(12));status.setBackgroundColor(Color.rgb(28,41,60));
        button("完整安装说明 / 其他路线",()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://marcotv.wlj9919.top/install/"))));text("此助手安装在安卓手机上，目标 APK 安装到电视。\n无广告、不上传 IP 或设备信息。若付费购买，请申请退款。",13,muted);
        android.text.TextWatcher watcher=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!busy)disconnect();}public void afterTextChanged(android.text.Editable e){}};ip.addTextChangedListener(watcher);port.addTextChangedListener(watcher);
    }
    private TextView text(String t,int size,int color){TextView v=new TextView(this);v.setText(t);v.setTextColor(color);v.setTextSize(size);v.setPadding(0,dp(10),0,dp(10));box.addView(v);return v;}
    private EditText field(String hint,String value){EditText v=new EditText(this);v.setSingleLine(true);v.setTextColor(ink);v.setHintTextColor(muted);v.setHint(hint);v.setInputType(InputType.TYPE_CLASS_PHONE);v.setText(value);box.addView(v);return v;}
    private Button button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);box.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));b.setOnClickListener(v->action.run());return b;}
    private void ui(Runnable r){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())r.run();});}
    private void say(String s){ui(()->status.setText(s));}
    private interface Work{void run()throws Exception;}
    private void controls(){connect.setEnabled(!busy);find.setEnabled(!busy);ip.setEnabled(!busy);port.setEnabled(!busy);install.setEnabled(!busy&&adb!=null);open.setEnabled(!busy&&adb!=null);}
    private void run(Work job){if(busy)return;busy=true;controls();worker.execute(()->{try{job.run();}catch(Exception e){AdbWire a=adb;adb=null;if(a!=null)a.close();say("未完成："+(e instanceof SocketTimeoutException?"连接超时，请确认同一网络、电视调试和授权弹窗。":e instanceof ConnectException?"电视未接受连接，请核对 IP、实际端口及调试开关。":e.getMessage()));}finally{ui(()->{busy=false;controls();});}});}
    private AdbWire require()throws IOException{AdbWire a=adb;if(a==null)throw new IOException("请先连接电视");return a;}
    private void disconnect(){generation++;AdbWire a=adb;adb=null;if(a!=null)a.close();identity="";if(install!=null){install.setEnabled(false);open.setEnabled(false);}}
    private void connect(){final String host=ip.getText().toString().trim();final int p;try{p=Integer.parseInt(port.getText().toString());}catch(Exception e){say("端口请输入数字");return;}disconnect();final int attempt=generation;run(()->{say("正在连接；请留意电视授权弹窗…");AdbWire a=new AdbWire();adb=a;try{if(attempt!=generation)throw new IOException("连接已取消");a.connect(host,p,AdbWire.key(getFilesDir()),this::say);int sdk=Integer.parseInt(a.shell("getprop ro.build.version.sdk"));if(sdk<23)throw new IOException("电视系统需为 Android 6.0 以上");String name=a.shell("getprop ro.product.manufacturer")+" "+a.shell("getprop ro.product.model");if(attempt!=generation||adb!=a)throw new IOException("连接已取消");identity=name;say("已连接："+name+"（Android API "+sdk+"）\n核对型号后点击安装。连接成功不代表所有桌面管理功能适配。");}catch(Exception e){a.close();throw e;}});}
    private void verify()throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");long size=0;try(InputStream in=getAssets().open("MarcoTV.apk")){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){d.update(b,0,n);size+=n;}}StringBuilder h=new StringBuilder();for(byte b:d.digest())h.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(size!=ReleaseInfo.SIZE||!h.toString().equals(ReleaseInfo.SHA))throw new IOException("内置安装包校验失败，请从官方站重新下载助手");}
    private void install(){progress.setProgress(0);run(()->{AdbWire a=require();verify();say("安装包校验通过，正在传送…");String path="/data/local/tmp/marcotv-phone-installer.apk";try{try(InputStream in=getAssets().open("MarcoTV.apk")){a.push(in,ReleaseInfo.SIZE,path,n->ui(()->progress.setProgress(n)));}say("电视正在安装，请稍候…");String r=a.shell("pm install -r "+path);boolean ok=false;for(String line:r.split("\n"))if("Success".equals(line.trim()))ok=true;if(!ok)throw new IOException(installError(r));say("安装成功。点击打开桌面，在电视按首次引导选择需要的功能。\n若之前启用系统最近任务辅助服务，更新后仍需重新启动。");}finally{try{a.shell("rm -f "+path);}catch(Exception ignored){}}});}
    public static String installError(String r){if(r.contains("VERSION_DOWNGRADE"))return "电视已有更高版本，已停止安装，不会降级";if(r.contains("UPDATE_INCOMPATIBLE")||r.contains("SIGNATURE"))return "签名不一致，原应用与数据已保留；请先备份并核对来源，不要直接卸载";if(r.contains("INSUFFICIENT_STORAGE"))return "电视空间不足，请释放空间后重试";if(r.contains("USER_RESTRICTED")||r.contains("SECURITY"))return "电视限制了安装，请核对本机安装权限";return "电视未确认安装成功，请查看电视的权限和安装提示";}
    private void discover(){run(()->{say("正在查找同网开放 5555 的设备…");Set<String> hosts=new LinkedHashSet<>();Enumeration<NetworkInterface> interfaces=NetworkInterface.getNetworkInterfaces();while(interfaces!=null&&interfaces.hasMoreElements()&&hosts.size()<508){NetworkInterface ni=interfaces.nextElement();if(!ni.isUp()||ni.isLoopback()||ni.isVirtual())continue;for(InterfaceAddress ia:ni.getInterfaceAddresses()){if(!(ia.getAddress() instanceof Inet4Address)||ia.getNetworkPrefixLength()!=24)continue;String own=ia.getAddress().getHostAddress();try{AdbWire.address(own);}catch(Exception e){continue;}String prefix=own.substring(0,own.lastIndexOf('.')+1);for(int i=1;i<255;i++)if(!(prefix+i).equals(own))hosts.add(prefix+i);if(hosts.size()>=508)break;}}
        ExecutorService scan=Executors.newFixedThreadPool(16);List<String> found=Collections.synchronizedList(new ArrayList<>());try{for(String host:hosts)scan.execute(()->{try(Socket s=new Socket()){s.connect(new InetSocketAddress(host,5555),250);found.add(host);}catch(Exception ignored){}});scan.shutdown();if(!scan.awaitTermination(12,TimeUnit.SECONDS))scan.shutdownNow();}finally{scan.shutdownNow();}Collections.sort(found);if(found.isEmpty()){say("没有找到。请手动填写电视 IP 和实际连接端口；不同网段、访客隔离或调试关闭都可能导致找不到。");return;}String[] choices=found.toArray(new String[0]);ui(()->new AlertDialog.Builder(this).setTitle("选择候选设备，连接后核对型号").setItems(choices,(d,w)->{disconnect();ip.setText(choices[w]);port.setText("5555");}).setNegativeButton("取消",null).show());say("找到 "+choices.length+" 个候选设备。选择后连接，并在电视确认授权。");});}
    protected void onDestroy(){disconnect();worker.shutdownNow();super.onDestroy();}
}
